const d = $json;

const system = 'You are a YouTube history researcher. Output ONLY raw JSON. No markdown. No code fences. No commentary. Start your response with { and end with }.';

const user = 'TOPIC: ' + d.topic + '\n\nReturn 10 factual claims as JSON:\n{"topic":"...","claims":[{"claim":"...","confidence":"high","safe_wording":"..."}],"common_myths":["..."],"modern_comparisons":["..."],"story_angles":["..."]}';

const model = d.groqModel || 'openai/gpt-oss-120b';
const researchBody = {
  model,
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  temperature: 1,
  max_tokens: 8000
};
return [{ json: { ...d, researchBody } }];

const raw = $json.choices?.[0]?.message?.content || '';
if (!raw) throw new Error('Research model returned no content');

function parseResearchJson(rawStr) {
  let clean = rawStr.replace(/```json/gi, '').replace(/```/g, '').trim();
  const first = clean.indexOf('{');
  const last = clean.lastIndexOf('}');
  if (first < 0 || last <= first) throw new Error('Research response did not contain JSON');
  let str = clean.slice(first, last + 1);
  str = str.replace(/\*\*/g, '');
  str = str.replace(/,\s*([}\]])/g, '$1');
  try { return JSON.parse(str); } catch (e) {
    const claims = [];
    const claimMatches = clean.match(/\{[^{}]*"claim"[\s\S]*?\}/g) || [];
    for (const cm of claimMatches) {
      const cText = (cm.match(/"claim"\s*:\s*"([^"]+)"/) || [])[1] || '';
      const cConf = (cm.match(/"confidence"\s*:\s*"([^"]+)"/) || [])[1] || 'medium';
      const cSafe = (cm.match(/"safe_wording"\s*:\s*"([^"]+)"/) || [])[1] || cText;
      if (cText.length > 5) claims.push({ claim: cText, confidence: cConf, safe_wording: cSafe });
    }
    if (claims.length >= 5) return { topic: d.topic, core_question: '', claims };
    throw new Error('Research JSON parse failed: ' + e.message);
  }
}

let data;
try { data = parseResearchJson(raw); } catch (e) { throw new Error('Research JSON parse failed: ' + e.message); }
if (!Array.isArray(data.claims) || data.claims.length < 5) throw new Error('Research brief contains too few claims');

const source = $('🎯 Topic + Voice').first().json;
return [{ json: { ...source, research: data, researchClaims: data.claims, researchMyths: data.common_myths || [], researchComparisons: data.modern_comparisons || [], researchAngles: data.story_angles || [] } }];

const raw = $json.choices?.[0]?.message?.content || '';
const finish = $json.choices?.[0]?.finish_reason || 'unknown';
if (!raw) throw new Error('Groq returned no content. finish_reason=' + finish + '. max_tokens too low for reasoning model.');

function parseScript(str) {
  let s = str.replace(/```json/gi,'').replace(/```/g,'').trim();
  const fi=s.indexOf('{'),la=s.lastIndexOf('}');
  if(fi<0||la<=fi) throw new Error('No JSON in response');
  s=s.slice(fi,la+1).replace(/,\s*([}\]])/g,'$1').replace(/\*\*/g,'');
  try{return JSON.parse(s);}catch(e){}
  try{return JSON.parse(s.replace(/(:\s*")((?:[^"\\]|\\.)*)(",?)/g,function(_,p,m,q){return p+m.replace(/(?<!\\)"/g,"'")+q;}));}catch(e){}
  const scenes=[];const rx=/"narration"\s*:\s*"([^"]{10,})"/g;let m,i=1;
  while((m=rx.exec(s))!==null) scenes.push({n:i++,narration:m[1],caption:'',visual_action:'ancient scene [CAMP]',camera:'slow_zoom_in'});
  if(scenes.length>=15) return {topic:$('🎯 Topic + Voice').first().json.topic,youtube_title:$('🎯 Topic + Voice').first().json.topic,youtube_description:'',thumbnail_prompt:'ancient human scene',scenes,shorts:[]};
  throw new Error('Parse failed. scenes='+scenes.length+' finish='+finish);
}

let data;
try{data=parseScript(raw);}catch(e){throw new Error('Script parse failed: '+e.message);}
if(!Array.isArray(data.scenes)||data.scenes.length<15) throw new Error('Too few scenes: '+(data.scenes?.length||0));

const source=$('🎯 Topic + Voice').first().json;
const allowedCam=['static','slow_zoom_in','slow_zoom_out'];
const allowedTags=['[CAMP]','[MODERN]','[COMPARE]','[REACTION]','[TIMELINE]','[MODERN_GAG]','[COMIC_CLOSEUP]'];

const scenes=data.scenes.slice(0,72).map((s,i)=>{
  const va=String(s.visual_action||'ancient human reacting [REACTION]').trim();
  const hasTag=allowedTags.some(t=>va.includes(t));
  const visual_action=hasTag?va:va+' [REACTION]';
  let caption=String(s.caption||'').trim().toUpperCase();
  if(!caption||caption.length<3){
    caption=String(s.narration||'').trim().split(/\s+/).slice(0,5).join(' ').toUpperCase();
  }
  // Keep caption short and clean for drawtext
  caption=caption.replace(/['"\\:;|<>{}[\]!@#$%^&*()+]/g,'').substring(0,50).trim();
  return {
    n:Number(s.n||i+1),
    narration:String(s.narration||'').trim(),
    caption,
    visual_action,
    doodle_prompt:visual_action,
    camera:allowedCam.includes(s.camera)?s.camera:'slow_zoom_in',
    on_screen_text:caption,
    sound_cue:'',
    fact_confidence:'medium'
  };
}).filter(s=>s.narration.length>10);

let shorts=Array.isArray(data.shorts)?data.shorts.slice(0,7).map((s,i)=>{
  let start=Math.max(1,Math.min(scenes.length,Number(s.start_scene)||1));
  let end=Math.max(1,Math.min(scenes.length,Number(s.end_scene)||start+7));
  if(end<start)[start,end]=[end,start];
  return{short_id:i+1,title:String(s.title||'').trim(),description:String(s.description||'').trim(),hook:String(s.hook||'').trim(),start_scene:start,end_scene:end};
}):[];
if(!shorts.length){
  const cnt=Math.min(6,Math.max(3,Math.floor(scenes.length/8)));
  const span=Math.floor(scenes.length/cnt);
  for(let i=0;i<cnt;i++){
    const start=i*span+1;
    const end=(i===cnt-1)?scenes.length:(i+1)*span;
    shorts.push({short_id:i+1,title:String(data.youtube_title||source.topic||'Short')+' Pt.'+(i+1),description:scenes[start-1]?.narration?.slice(0,100)||'',hook:scenes[start-1]?.narration?.slice(0,60)||'',start_scene:start,end_scene:end});
  }
}

const totalWords=scenes.reduce((n,s)=>n+s.narration.split(/\s+/).filter(Boolean).length,0);
return [{json:{
  ...source,
  topic:data.topic||source.topic,
  youtube_title:data.youtube_title||source.topic,
  title_candidates:Array.isArray(data.title_candidates)?data.title_candidates:[],
  youtube_description:String(data.youtube_description||''),
  youtube_tags:Array.isArray(data.youtube_tags)?data.youtube_tags.join(', '):String(data.youtube_tags||''),
  thumbnail_prompt:String(data.thumbnail_prompt||'ancient human documentary cartoon'),
  hook:String(data.hook||''),
  scenes,shorts,totalWords,
  estimatedMinutes:Number((totalWords/140).toFixed(2)),
  generationAttempt:1
}}];

const d=$json;const words=d.totalWords;const minutes=words/140;const scenes=d.scenes.length;
const needsExpansion=words<1750||scenes<45;
return [{json:{...d,needsExpansion,tooLong:words>2550||scenes>75,runtimeMinutes:Number(minutes.toFixed(2)),runtimeStatus:words>=1750&&scenes>=45?'PASS':'REVIEW'}}];

const d=$json;
if((d.generationAttempt||1)>=2) throw new Error('Script too short after expansion: '+d.totalWords+' words');
const existing=d.scenes.slice(0,20).map(s=>s.n+': '+s.narration).join('\n');
const system='Output ONLY raw JSON. No markdown. Start with { end with }.';
const user='Script is too short ('+d.totalWords+' words). Expand to 1900+ words / 50+ scenes.\n\nCurrent scenes:\n'+existing+'\n\nReturn full expanded scenes JSON ONLY:\n{"scenes":[{"n":1,"narration":"...","visual_action":"... [CAMP]","camera":"slow_zoom_in"}'+'}';
const model=d.groqModel||'openai/gpt-oss-120b';
const expansionBody={model,messages:[{role:'system',content:system},{role:'user',content:user}],temperature:1,max_tokens:20000};
return [{json:{...d,generationAttempt:2,expansionBody}}];

const raw=$json.choices?.[0]?.message?.content||'';
if(!raw) throw new Error('Expansion returned no content');
function parse(str){let s=str.replace(/```json/gi,'').replace(/```/g,'').trim();const fi=s.indexOf('{'),la=s.lastIndexOf('}');if(fi<0||la<=fi)throw new Error('No JSON');s=s.slice(fi,la+1).replace(/,\s*([}\]])/g,'$1');try{return JSON.parse(s);}catch(e){}const scenes=[];const rx=/"narration"\s*:\s*"([^"]{10,})"/g;let m,i=1;while((m=rx.exec(s))!==null)scenes.push({n:i++,narration:m[1],visual_action:'ancient scene [CAMP]',camera:'slow_zoom_in'});if(scenes.length>=15)return{scenes};throw new Error('Expansion parse failed');}
let data;try{data=parse(raw);}catch(e){throw new Error('Expansion parse: '+e.message);}
if(!Array.isArray(data.scenes))throw new Error('Expanded script missing scenes');
const source=$('🎯 Topic + Voice').first().json;
const allowed=['static','slow_zoom_in','slow_zoom_out','pan_left','pan_right','quick_zoom','shake'];
const scenes=data.scenes.slice(0,72).map((s,i)=>({n:Number(s.n||i+1),narration:String(s.narration||'').trim(),visual_action:String(s.visual_action||'character reacting [CAMP]').trim(),doodle_prompt:String(s.doodle_prompt||s.visual_action||'history scene').trim(),camera:allowed.includes(s.camera)?s.camera:'slow_zoom_in',on_screen_text:'',sound_cue:'',fact_confidence:'medium'})).filter(s=>s.narration.length>10);
const totalWords=scenes.reduce((n,s)=>n+s.narration.split(/\s+/).filter(Boolean).length,0);
if(scenes.length<28)throw new Error('Expansion only '+scenes.length+' scenes');
if(totalWords<1400)throw new Error('Expansion only '+totalWords+' words');
let shorts=[];const cnt=Math.min(6,Math.max(3,Math.floor(scenes.length/8)));const span=Math.floor(scenes.length/cnt);
for(let i=0;i<cnt;i++){const start=i*span+1;const end=(i===cnt-1)?scenes.length:(i+1)*span;shorts.push({short_id:i+1,title:String(data.youtube_title||source.topic||'Short')+' Pt.'+(i+1),description:scenes[start-1]?.narration?.slice(0,100)||'',hook:scenes[start-1]?.narration?.slice(0,60)||'',start_scene:start,end_scene:end});}
return [{json:{...source,topic:data.topic||source.topic,youtube_title:data.youtube_title||source.youtube_title||source.topic,title_candidates:data.title_candidates||source.title_candidates||[],youtube_description:data.youtube_description||source.youtube_description||'',youtube_tags:Array.isArray(data.youtube_tags)?data.youtube_tags.join(', '):String(data.youtube_tags||source.youtube_tags||''),thumbnail_prompt:data.thumbnail_prompt||source.thumbnail_prompt||'ancient human scene',hook:data.hook||source.hook||'',scenes,shorts,totalWords,estimatedMinutes:Number((totalWords/140).toFixed(2)),generationAttempt:2}}];

const d=$json;const words=d.totalWords;const minutes=words/140;
if(words<1400||words>2700)throw new Error('Final script word count invalid: '+words);
if(d.scenes.length<38||d.scenes.length>75)throw new Error('Final scene count invalid: '+d.scenes.length);
return [{json:{...d,estimatedMinutes:Number(minutes.toFixed(2)),runtimeStatus:'PASS'}}];

