DUR=$(ffprobe -v error -show_entries format=duration -of default=nk=1:nw=1 "$VDIR/voice_${IDX}.m4a");
DUR=$(awk -v d="$DUR" 'BEGIN { dur=d+0.15; if(dur<2)dur=2; if(dur>60)dur=60; printf "%.2f",dur }');
CAM="{{ $('🔁 One Scene At A Time').first().json.scene.camera || 'slow_zoom_in' }}";

# Zoom filter — reference videos use gentle slow zoom only
case "$CAM" in
  slow_zoom_in)  ZFILTER="zoompan=z='min(zoom+0.0007,1.12)':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=1:s=1920x1080:fps=24";;
  slow_zoom_out) ZFILTER="zoompan=z='if(lte(zoom,1.0),1.12,max(zoom-0.0007,1.0))':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=1:s=1920x1080:fps=24";;
  *)             ZFILTER="scale=1920:1080:force_original_aspect_ratio=increase:flags=lanczos,crop=1920:1080";;
esac;

# Caption text — sanitise for drawtext
RAW="{{ $('🔁 One Scene At A Time').first().json.scene.caption || $('🔁 One Scene At A Time').first().json.scene.on_screen_text || '' }}";
CAPTION=$(echo "$RAW" | tr -d "'\"\\:;|<>{}[]()!@#\$%^&*+=" | sed 's/  */ /g' | cut -c1-45);

# Find bold font
FONT="";
for F in \
  /usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf \
  /usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf \
  /usr/share/fonts/truetype/freefont/FreeSansBold.ttf \
  /usr/share/fonts/liberation/LiberationSans-Bold.ttf \
  /usr/share/fonts/opentype/noto/NotoSans-Bold.ttf \
  /usr/share/fonts/noto/NotoSans-Bold.ttf; do
  if [ -f "$F" ]; then FONT="$F"; break; fi;
done;

# Caption overlay — white text, 4px black border, bottom-centre, matches reference videos
if [ -n "$CAPTION" ] && [ -n "$FONT" ]; then
  ESC=$(echo "$CAPTION" | sed "s/:/\\\\:/g; s/%/\\\\%/g");
  TEXTF=",drawtext=fontfile='${FONT}':text='${ESC}':fontsize=68:fontcolor=white:bordercolor=black:borderw=4:x=(w-text_w)/2:y=h-110:line_spacing=8";
else
  TEXTF="";
fi;

# Full filter chain
if [ "$CAM" = "static" ]; then
  VF="scale=1920:1080:force_original_aspect_ratio=increase:flags=lanczos,crop=1920:1080,unsharp=3:3:0.3:3:3:0.0,eq=contrast=1.04:brightness=0.005:saturation=1.05${TEXTF},format=yuv420p";
else
  VF="scale=1920:1080:force_original_aspect_ratio=increase:flags=lanczos,crop=1920:1080,${ZFILTER},unsharp=3:3:0.3:3:3:0.0,eq=contrast=1.04:brightness=0.005:saturation=1.05${TEXTF},format=yuv420p";
fi;

ffmpeg -nostdin -y -threads 2 \
  -loop 1 -i "$VDIR/scene_${IDX}.png" \
  -i "$VDIR/voice_${IDX}.m4a" \
  -vf "$VF" -af "apad" -t "$DUR" \
  -map 0:v:0 -map 1:a:0 \
  -c:v libx264 -preset veryfast -crf 20 \
  -profile:v high -level 4.1 \
  -color_range tv -colorspace bt709 -color_primaries bt709 -color_trc bt709 \
  -c:a aac -b:a 192k -ar 48000 -ac 2 \
  -movflags +faststart \
  "$VDIR/scene_${IDX}_out.mp4";
test -s "$VDIR/scene_${IDX}_out.mp4"

